import base64
import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _normalize_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value.strip()
    return str(value).strip()


def _extract_kv(analysis: Dict[str, Any], key_candidates: List[str]) -> Optional[str]:
    expense_docs = analysis.get("ExpenseDocuments", []) or []
    for doc in expense_docs:
        summary_fields = doc.get("SummaryFields", []) or []
        for field in summary_fields:
            ft = _normalize_text(((field or {}).get("Type") or {}).get("Text")).lower()
            if ft in key_candidates:
                val = (field or {}).get("ValueDetection", {}) or {}
                text = _normalize_text(val.get("Text"))
                if text:
                    return text
    return None


def _extract_merchant(analysis: Dict[str, Any]) -> Optional[str]:
    candidates = ["merchant", "vendor", "seller", "supplier", "store"]
    return _extract_kv(analysis, candidates)


def _extract_total(analysis: Dict[str, Any]) -> Optional[str]:
    candidates = ["total", "amount due", "balance due", "grand total", "invoice total"]
    return _extract_kv(analysis, candidates)


def _extract_tax(analysis: Dict[str, Any]) -> Optional[str]:
    candidates = ["tax", "sales tax", "vat", "gst", "hst", "pst"]
    return _extract_kv(analysis, candidates)


def _extract_items(analysis: Dict[str, Any]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    expense_docs = analysis.get("ExpenseDocuments", []) or []
    for doc in expense_docs:
        line_items_groups = doc.get("LineItemGroups", []) or []
        for group in line_items_groups:
            for line_item in (group.get("LineItems", []) or []):
                item: Dict[str, Any] = {}
                for field in (line_item.get("LineItemExpenseFields", []) or []):
                    field_type = _normalize_text(((field or {}).get("Type") or {}).get("Text")).lower()
                    value = _normalize_text(((field or {}).get("ValueDetection") or {}).get("Text"))
                    if not value:
                        continue
                    if field_type in {"item", "description", "product", "name"}:
                        item["description"] = value
                    elif field_type in {"quantity", "qty"}:
                        item["quantity"] = value
                    elif field_type in {"unit price", "price", "rate"}:
                        item["unit_price"] = value
                    elif field_type in {"amount", "total", "line total", "line amount"}:
                        item["amount"] = value
                if item:
                    items.append(item)
    return items


def extract_receipt(file_path: str) -> Dict[str, Any]:
    """
    Extract merchant, tax, total, and items from a receipt using Amazon Textract AnalyzeExpense.

    Returns a dictionary with keys:
      - merchant
      - tax
      - total
      - items
    """
    textract = boto3.client("textract")
    with open(file_path, "rb") as f:
        image_bytes = f.read()

    response = textract.analyze_expense(Document={"Bytes": image_bytes})

    merchant = _extract_merchant(response)
    tax = _extract_tax(response)
    total = _extract_total(response)
    items = _extract_items(response)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
        "raw": response,
    }


def extract_receipt_from_base64(base64_data: str) -> Dict[str, Any]:
    """
    Same as extract_receipt, but accepts a base64-encoded receipt image/PDF payload.
    """
    textract = boto3.client("textract")
    image_bytes = base64.b64decode(base64_data)

    response = textract.analyze_expense(Document={"Bytes": image_bytes})

    merchant = _extract_merchant(response)
    tax = _extract_tax(response)
    total = _extract_total(response)
    items = _extract_items(response)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
        "raw": response,
    }
